import numpy as np, torch, model
net=model.load()
ub=np.array([-1.18,-3.39]); ub/=np.linalg.norm(ub); up=np.array([-ub[1],ub[0]])
def dec(x0,c,cfg=None):
    x=torch.tensor(x0); cc=torch.tensor(c)
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,_=net.velocity(x,t,cc,(),count=False)
        if cfg is not None:
            w,th,g,lo,hi=cfg
            h=torch.relu(x@torch.tensor(w,dtype=torch.float32)-th)
            f=((k>=lo)&(k<hi))
            v=v - f*h[:,None]*torch.tensor(g*up,dtype=torch.float32)
        x=x-v/20
    return x.numpy()
